31: @RequiresApi(26)
32: public final class StreamingTranscoder {
33: 
34:   private static final String TAG = Log.tag(StreamingTranscoder.class);
35: 
36:   private final           MediaDataSource    dataSource;
37:   private final           long               upperSizeLimit;
38:   private final           long               inSize;
39:   private final           long               duration;
40:   private final           int                inputBitRate;
41:   private final           TranscodingQuality targetQuality;
42:   private final           boolean            transcodeRequired;
43:   private final           long               fileSizeEstimate;
44:   private final @Nullable TranscoderOptions  options;
45:   private final           boolean            allowAudioRemux;
46: 
47:   /**
48:    * @param upperSizeLimit A upper size to transcode to. The actual output size can be up to 10% smaller.
49:    */
50:   public StreamingTranscoder(@NonNull MediaDataSource dataSource,
51:                              @Nullable TranscoderOptions options,
52:                              @NonNull List<TranscodingConfig.QualityTier> configs,
53:                              long upperSizeLimit,
54:                              boolean allowAudioRemux)
55:       throws IOException, VideoSourceException
56:   {
57:     this.dataSource = dataSource;
58:     this.options    = options;
59:     this.allowAudioRemux = allowAudioRemux;
60: 
61:     final MediaMetadataRetriever mediaMetadataRetriever = new MediaMetadataRetriever();
62:     try {
63:       mediaMetadataRetriever.setDataSource(dataSource);
64:     } catch (RuntimeException e) {
65:       Log.w(TAG, "Unable to read datasource", e);
66:       throw new VideoSourceException("Unable to read datasource", e);
67:     }
68: 
69:     if (options != null && options.endTimeUs != 0) {
70:       this.duration = TimeUnit.MICROSECONDS.toMillis(options.endTimeUs - options.startTimeUs);
71:     } else {
72:       this.duration = getDuration(mediaMetadataRetriever);
73:     }
74: 
75:     this.inSize         = dataSource.getSize();
76:     this.inputBitRate   = TranscodingQuality.bitRate(inSize, duration);
77:     this.targetQuality  = TranscodingQuality.createFromQualityTiers(configs, duration);
78:     this.upperSizeLimit = upperSizeLimit;
79: 
80:     this.transcodeRequired = inputBitRate >= targetQuality.getTargetTotalBitRate() * 1.2 || inSize > upperSizeLimit || containsLocation(mediaMetadataRetriever) || options != null || !isH264(dataSource);
81:     if (!transcodeRequired) {
82:       Log.i(TAG, "Video is within 20% of target bitrate, below the size limit, contained no location metadata or custom options, and is already H.264.");
83:     }
84: 
85:     this.fileSizeEstimate   = targetQuality.getByteCountEstimate();
86:   }
87: 
88:   private StreamingTranscoder(@NonNull MediaDataSource dataSource,
89:                              @Nullable TranscoderOptions options,
90:                              String codec,
91:                              int videoBitrate,
92:                              int audioBitrate,
93:                              int shortEdge,
94:                              boolean allowAudioRemux)
95:       throws IOException, VideoSourceException
96:   {
97:     this.dataSource      = dataSource;
98:     this.options         = options;
99:     this.allowAudioRemux = allowAudioRemux;
100: 
101:     final MediaMetadataRetriever mediaMetadataRetriever = new MediaMetadataRetriever();
102:     try {
103:       mediaMetadataRetriever.setDataSource(dataSource);
104:     } catch (RuntimeException e) {
105:       Log.w(TAG, "Unable to read datasource", e);
106:       throw new VideoSourceException("Unable to read datasource", e);
107:     }
108: 
109:     this.inSize         = dataSource.getSize();
110:     this.duration       = getDuration(mediaMetadataRetriever);
111:     this.inputBitRate   = TranscodingQuality.bitRate(inSize, duration);
112:     this.targetQuality  = TranscodingQuality.createManuallyForTesting(codec, shortEdge, videoBitrate, audioBitrate, duration);
113:     this.upperSizeLimit = 0L;
114: 
115:     this.transcodeRequired = true;
116: 
117:     this.fileSizeEstimate   = targetQuality.getByteCountEstimate();
118:   }
119: 
120:   @VisibleForTesting
121:   public static StreamingTranscoder createManuallyForTesting(@NonNull MediaDataSource dataSource,
122:                                                              @Nullable TranscoderOptions options,
123:                                                              @NonNull @MediaConverter.VideoCodec String codec,
124:                                                              int videoBitrate,
125:                                                              int audioBitrate,
126:                                                              int shortEdge,
127:                                                              boolean allowAudioRemux)
128:       throws VideoSourceException, IOException
129:   {
130:     return new StreamingTranscoder(dataSource, options, codec, videoBitrate, audioBitrate, shortEdge, allowAudioRemux);
131:   }
132: 
133:   /**
134:    * @return The total content size of the MP4 mdat box.
135:    */
136:   public long transcode(@NonNull Progress progress,
137:                         @NonNull OutputStream stream,
138:                         @Nullable TranscoderCancelationSignal cancelationSignal)
139:       throws IOException, EncodingException
140:   {
141:     float durationSec = duration / 1000f;
142: 
143:     NumberFormat numberFormat = NumberFormat.getInstance(Locale.US);
144: 
145:     Log.i(TAG, String.format(Locale.US,
146:                              "Transcoding:\n" +
147:                              "Target bitrate : %s + %s = %s\n" +
148:                              "Target format  : %dp\n" +
149:                              "Video duration : %.1fs\n" +
150:                              "Size limit     : %s kB\n" +
151:                              "Estimate       : %s kB\n" +
152:                              "Input size     : %s kB\n" +
153:                              "Input bitrate  : %s bps",
154:                              numberFormat.format(targetQuality.getTargetVideoBitRate()),
155:                              numberFormat.format(targetQuality.getTargetAudioBitRate()),
156:                              numberFormat.format(targetQuality.getTargetTotalBitRate()),
157:                              targetQuality.getOutputResolution(),
158:                              durationSec,
159:                              numberFormat.format(upperSizeLimit / 1024),
160:                              numberFormat.format(fileSizeEstimate / 1024),
161:                              numberFormat.format(inSize / 1024),
162:                              numberFormat.format(inputBitRate)));
163: 
164:     final boolean sizeLimitEnabled = 0 < upperSizeLimit;
165: 
166:     if (sizeLimitEnabled && upperSizeLimit < fileSizeEstimate) {
167:       throw new VideoSizeException("Size constraints could not be met! upperSizeLimit: " + upperSizeLimit + ", fileSizeEstimate: " + fileSizeEstimate);
168:     }
169: 
170:     final long startTime = System.currentTimeMillis();
171: 
172:     final MediaConverter converter = new MediaConverter();
173: 
174:     converter.setInput(new MediaDataSourceMediaInput(dataSource));
175:     final CountingOutputStream outStream;
176:     if (sizeLimitEnabled) {
177:       outStream = new CountingOutputStream(new LimitedSizeOutputStream(stream, upperSizeLimit));
178:     } else {
179:       outStream = new CountingOutputStream(stream);
180:     }
181:     converter.setOutput(outStream);
182:     converter.setVideoCodec(targetQuality.getCodec());
183:     converter.setVideoResolution(targetQuality.getOutputResolution());
184:     converter.setVideoBitrate(targetQuality.getTargetVideoBitRate());
185:     converter.setAudioBitrate(targetQuality.getTargetAudioBitRate());
186:     converter.setAllowAudioRemux(allowAudioRemux);
187: 
188:     if (options != null) {
189:       if (options.endTimeUs > 0) {
190:         long timeFrom = options.startTimeUs / 1000;
191:         long timeTo   = options.endTimeUs   / 1000;
192:         converter.setTimeRange(timeFrom, timeTo);
193:         Log.i(TAG, String.format(Locale.US, "Trimming:\nTotal duration: %d\nKeeping: %d..%d\nFinal duration:(%d)", duration, timeFrom, timeTo, timeTo - timeFrom));
194:       }
195:     }
196: 
197:     converter.setListener(percent -> {
198:       progress.onProgress(percent);
199:       return cancelationSignal != null && cancelationSignal.isCanceled();
200:     });
201: 
202:     long mdatSize = converter.convert();
203: 
204:     long  outSize           = outStream.getCount();
205:     float encodeDurationSec = (System.currentTimeMillis() - startTime) / 1000f;
206: 
207:     Log.i(TAG, String.format(Locale.US,
208:                              "Transcoding complete:\n" +
209:                              "Transcode time : %.1fs (%.1fx)\n" +
210:                              "Output size    : %s kB\n" +
211:                              "  of Original  : %.1f%%\n" +
212:                              "  of Estimate  : %.1f%%\n" +
213:                              "Output bitrate : %s bps",
214:                              encodeDurationSec,
215:                              durationSec / encodeDurationSec,
216:                              numberFormat.format(outSize / 1024),
217:                              (outSize * 100d) / inSize,
218:                              (outSize * 100d) / fileSizeEstimate,
219:                              numberFormat.format(TranscodingQuality.bitRate(outSize, duration))));
220: 
221:     if (sizeLimitEnabled && outSize > upperSizeLimit) {
222:       throw new VideoSizeException("Size constraints could not be met!");
223:     }
224: 
225:     stream.flush();
226: 
227:     return mdatSize;
228:   }
229: 
230:   public boolean isTranscodeRequired() {
231:     return transcodeRequired;
232:   }
233: 
234:   private static long getDuration(MediaMetadataRetriever mediaMetadataRetriever) throws VideoSourceException {
235:     String durationString = mediaMetadataRetriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION);
236:     if (durationString == null) {
237:       throw new VideoSourceException("Cannot determine duration of video, null meta data");
238:     }
239:     try {
240:       long duration = Long.parseLong(durationString);
241:       if (duration <= 0) {
242:         throw new VideoSourceException("Cannot determine duration of video, meta data: " + durationString);
243:       }
244:       return duration;
245:     } catch (NumberFormatException e) {
246:       throw new VideoSourceException("Cannot determine duration of video, meta data: " + durationString, e);
247:     }
248:   }
249: 
250:   private static boolean containsLocation(MediaMetadataRetriever mediaMetadataRetriever) {
251:     String locationString = mediaMetadataRetriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_LOCATION);
252:     return locationString != null;
253:   }
254: 
255:   private static boolean isH264(@NonNull MediaDataSource dataSource) {
256:     MediaExtractor extractor = new MediaExtractor();
257:     try {
258:       extractor.setDataSource(dataSource);
259:       for (int i = 0; i < extractor.getTrackCount(); i++) {
260:         MediaFormat format = extractor.getTrackFormat(i);
261:         String mime = format.getString(MediaFormat.KEY_MIME);
262:         if (mime != null && mime.startsWith("video/")) {
263:           return MediaConverter.VIDEO_CODEC_H264.equals(mime);
264:         }
265:       }
266:       return false;
267:     } catch (IOException e) {
268:       Log.w(TAG, "Unable to check video codec", e);
269:       return false;
270:     } finally {
271:       extractor.release();
272:     }
273:   }
274: 
275:   public interface Progress {
276:     void onProgress(int percent);
277:   }
278: 
279:   private static class LimitedSizeOutputStream extends FilterOutputStream {
280: 
281:     private final long sizeLimit;
282:     private       long written;
283: 
284:     LimitedSizeOutputStream(@NonNull OutputStream inner, long sizeLimit) {
285:       super(inner);
286:       this.sizeLimit = sizeLimit;
287:     }
288: 
289:     @Override public void write(int b) throws IOException {
290:       incWritten(1);
291:       out.write(b);
292:     }
293: 
294:     @Override public void write(byte[] b, int off, int len) throws IOException {
295:       incWritten(len);
296:       out.write(b, off, len);
297:     }
298: 
299:     private void incWritten(int len) throws IOException {
300:       long newWritten = written + len;
301:       if (newWritten > sizeLimit) {
302:         Log.w(TAG, String.format(Locale.US, "File size limit hit. Wrote %d, tried to write %d more. Limit is %d", written, len, sizeLimit));
303:         throw new VideoSizeException("File size limit hit");
304:       }
305:       written = newWritten;
306:     }
307:   }
308: }

