fun getOrCreateVideoTrimData(uri: Uri): VideoTrimData {
    return (editorStateMap[uri] as? EditorState.VideoTrim)?.videoTrimData ?: VideoTrimData()
  }

  fun getEditorState(uri: Uri): EditorState? = editorStateMap[uri]

  /**
   * Whether this particular item is one the user is allowed to remove the audio from.
   *
   * Only an ordinary video qualifies: images and documents have no audio track to remove, and a video GIF is
   * looped back as-is by the player rather than being sent as a video, so it isn't an editable video at all. The
   * feature flag is honored here too, so a build without audio removal never offers the control at all.
   */
  fun isAudioRemovalAvailable(media: Media?, editorState: EditorState?): Boolean {
    if (!MediaConstraints.isMuteVideoAudioAvailable()) {
      return false
    } else if (media == null || !ContentTypeUtil.isVideoType(media.contentType)) {
      return false
    } else if (ContentTypeUtil.isDocumentType(media.contentType) || media.isVideoGif) {
      return false
    }

    // A video GIF carries its own (unremovable) audio, so an existing non-trim editor state means "not editable".
    return editorState == null || editorState is EditorState.VideoTrim
  }

  /** Whether audio removal should be offered for whatever the pager is currently focused on. */
  val isFocusedMediaAudioRemovalAvailable: Boolean
    get() = isAudioRemovalAvailable(focusedMedia, focusedMedia?.let { editorStateMap[it.uri] })

  /**
   * The focused video's own audio-removal choice. Reading this after changing focus yields the newly focused item's
   * setting rather than the previous item's.
   */
  val isFocusedMediaMuted: Boolean
    get() = (editorStateMap[focusedMedia?.uri] as? EditorState.VideoTrim)?.isMuted == true

  fun isMuted(media: Media?): Boolean {
    return (editorStateMap[media?.uri] as? EditorState.VideoTrim)?.isMuted == true
  }

  /**
   * Replaces the editor state stored for a single item, leaving every other item's state — and the selection's
   * membership and order — exactly as it was.
   */
  fun withEditorState(uri: Uri, editorState: EditorState): MediaSendFlowState {
    return copy(editorStateMap = editorStateMap + (uri to editorState))
  }

  /** Drops any edit recorded for items that are no longer selected. */
  fun withoutEditorState(uris: Collection<Uri>): MediaSendFlowState {
    if (uris.isEmpty()) {
      return this
    }

    return copy(editorStateMap = editorStateMap - uris.toSet())
  }

  /** Every item that carries a video edit, in selection order, so the send path can prepare them all. */
  fun videoTrimStatesByUri(): Map<Uri, EditorState.VideoTrim> {
    return selectedMedia.mapNotNull { media ->
      (editorStateMap[media.uri] as? EditorState.VideoTrim)?.let { media.uri to it }
    }.toMap()
  }

