fun isAudioRemovalAvailable(media: Media?, editorState: EditorState?): Boolean {
    if (!MediaConstraints.isMuteVideoAudioAvailable()) {
      return false
    }

    if (media == null || !ContentTypeUtil.isVideoType(media.contentType)) {
      // Images and documents have no audio track to remove in the first place.
      return false
    }

