  private suspend fun discardPendingWork() {
    val flowState = current
    val selected = flowState.selectedMedia

    if (selected.isEmpty()) {
      hudCommandChannel.trySend(MediaSendFlowHudCommand.CloseScreen)
      return
    }

    // A camera-first flow whose one remaining item is the capture that just started it has nothing left to edit.
    // Throw that capture away and go back to the camera rather than leaving the user in an empty editor.
    val capture = flowState.cameraFirstCapture
    val isOnlyTheJustCapturedItem = flowState.isCameraFirst && capture != null &&
        selected.size == 1 && selected.first() == capture

    if (isOnlyTheJustCapturedItem) {
      // The capture is ours, not something the user picked out of their library, so its blob goes with it.
      mediaSendRepository.deleteBlobs(listOfNotNull(capture))
    }

    preUploadController.cancelUpload(selected.toSet())
    preUploadController.deleteAbandonedAttachments()

    update(
      flowState.copy(
        selectedMedia = emptyList(),
        focusedMedia = null,
        editorStateMap = emptyMap(),
        message = null,
        cameraFirstCapture = null,
        isSavingMedia = false
      )
    )

    if (isOnlyTheJustCapturedItem) {
      navigationChannel.trySend(MediaSendFlowEvent.NavigateToCamera)
    } else {
      hudCommandChannel.trySend(MediaSendFlowHudCommand.CloseScreen)
    }
  }

